#!/usr/bin/env node
// Keeps scripts/sandbox-contract.json equal to the chat page's generated contract.
//
//   node scripts/sync-contract.mjs            # fetch and replace
//   node scripts/sync-contract.mjs --check    # exit 1 when the vendored copy differs
//   node scripts/sync-contract.mjs --from <path-to-stage-checkout>   # copy from a local checkout
//
// The source of truth is contract/sandbox-contract.json in the chat page's repository
// (hearthroom/moonstage), generated by its contract.spec.ts from the runtime objects.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const LOCAL = path.join(ROOT, 'scripts/sandbox-contract.json');
const URL = process.env.HEARTHROOM_CONTRACT_URL || 'https://raw.githubusercontent.com/hearthroom/moonstage/main/contract/sandbox-contract.json';
const args = process.argv.slice(2);
const from = args.includes('--from') ? args[args.indexOf('--from') + 1] : null;

async function upstream() {
  if (from) return readFileSync(path.join(from, 'contract/sandbox-contract.json'), 'utf8');
  const r = await fetch(URL);
  if (r.status === 404) { console.log(`△ ${URL} does not exist yet (the chat page has not published its contract); nothing to compare`); process.exit(0); }
  if (!r.ok) throw new Error(`${URL}: ${r.status}`);
  return await r.text();
}

const theirs = (await upstream()).trim();
let ours = '';
try { ours = readFileSync(LOCAL, 'utf8').trim(); } catch { /* first sync */ }
if (theirs === ours) { console.log('✔ sandbox-contract.json is current'); process.exit(0); }
if (args.includes('--check')) {
  console.log('✖ scripts/sandbox-contract.json differs from the chat page\'s contract; run node scripts/sync-contract.mjs, then npm test (facts-vs-contract) and update platform-facts.md');
  process.exit(1);
}
writeFileSync(LOCAL, theirs + '\n');
console.log(`✔ wrote ${LOCAL}; now run npm test and update references/platform-facts.md for any new name`);
